-- Phase 8B: deterministic crowds and live operational outcomes.
-- Additive and opt-in. No settlement, payroll, royalty, XP or reputation mutation occurs here.
ALTER TABLE public.festival_runtime_sessions ADD COLUMN ready_for_settlement boolean NOT NULL DEFAULT false;
ALTER TABLE public.festival_runtime_performances ADD COLUMN peak_audience integer NOT NULL DEFAULT 0, ADD COLUMN average_audience integer NOT NULL DEFAULT 0, ADD COLUMN crowd_response_score numeric, ADD COLUMN early_departures integer NOT NULL DEFAULT 0;
ALTER TABLE public.festival_runtime_jobs DROP CONSTRAINT festival_runtime_jobs_job_type_check;
ALTER TABLE public.festival_runtime_jobs ADD CONSTRAINT festival_runtime_jobs_job_type_check CHECK(job_type IN('start_site_setup','evaluate_gate_readiness','open_gates','close_gates','prepare_stage','start_performance','resolve_performance','start_changeover','complete_changeover','close_stage','close_public_site','start_site_clearance','complete_runtime','refresh_runtime_summary','update_crowd_distribution','update_crowd_mood','evaluate_incidents','resolve_automatic_incidents','evaluate_weather','update_vendor_sales','update_sponsor_activations','evaluate_staff_outcomes','evaluate_supplier_outcomes','capture_live_snapshot'));
ALTER TABLE public.festival_runtime_snapshots DROP CONSTRAINT festival_runtime_snapshots_snapshot_type_check;
ALTER TABLE public.festival_runtime_snapshots ADD CONSTRAINT festival_runtime_snapshots_snapshot_type_check CHECK(snapshot_type IN('runtime_created','day_open','periodic','day_close','runtime_complete','recovery','live','final_outcome'));

CREATE TABLE public.festival_runtime_weather(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),runtime_session_id uuid NOT NULL REFERENCES public.festival_runtime_sessions(id),runtime_day_id uuid NOT NULL REFERENCES public.festival_runtime_days(id),weather_state text NOT NULL CHECK(weather_state IN('clear','cloudy','light_rain','heavy_rain','hot','cold','high_wind','storm')),temperature_band text NOT NULL,ground_condition text NOT NULL,operational_impact integer NOT NULL CHECK(operational_impact BETWEEN 0 AND 100),seed text NOT NULL,formula_version text NOT NULL DEFAULT 'festival-operations-v1',calculated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(runtime_day_id));
CREATE TABLE public.festival_runtime_crowds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),runtime_session_id uuid NOT NULL REFERENCES public.festival_runtime_sessions(id),runtime_day_id uuid NOT NULL REFERENCES public.festival_runtime_days(id),admitted_count integer NOT NULL DEFAULT 0,allocated_count integer NOT NULL DEFAULT 0,unallocated_count integer NOT NULL DEFAULT 0,overall_mood text NOT NULL DEFAULT 'calm',energy integer NOT NULL DEFAULT 40 CHECK(energy BETWEEN 0 AND 100),satisfaction integer NOT NULL DEFAULT 50 CHECK(satisfaction BETWEEN 0 AND 100),seed text NOT NULL,formula_version text NOT NULL DEFAULT 'festival-crowd-v1',last_calculated_at timestamptz NOT NULL DEFAULT now(),version integer NOT NULL DEFAULT 1,UNIQUE(runtime_day_id));
CREATE TABLE public.festival_runtime_stage_crowds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),runtime_session_id uuid NOT NULL REFERENCES public.festival_runtime_sessions(id),runtime_day_id uuid NOT NULL REFERENCES public.festival_runtime_days(id),runtime_stage_id uuid NOT NULL REFERENCES public.festival_runtime_stages(id),runtime_performance_id uuid REFERENCES public.festival_runtime_performances(id),current_crowd integer NOT NULL DEFAULT 0 CHECK(current_crowd>=0),stage_capacity integer NOT NULL CHECK(stage_capacity>=0),crowd_share numeric NOT NULL DEFAULT 0 CHECK(crowd_share BETWEEN 0 AND 1),arrivals integer NOT NULL DEFAULT 0,departures integer NOT NULL DEFAULT 0,queue_size integer NOT NULL DEFAULT 0,mood text NOT NULL DEFAULT 'calm' CHECK(mood IN('bored','calm','interested','engaged','excited','jumping','ecstatic','tired','frustrated','leaving')),energy integer NOT NULL DEFAULT 40 CHECK(energy BETWEEN 0 AND 100),satisfaction integer NOT NULL DEFAULT 50 CHECK(satisfaction BETWEEN 0 AND 100),safety_pressure integer NOT NULL DEFAULT 0 CHECK(safety_pressure BETWEEN 0 AND 100),peak_audience integer NOT NULL DEFAULT 0,audience_total bigint NOT NULL DEFAULT 0,sample_count integer NOT NULL DEFAULT 0,seed text NOT NULL,formula_version text NOT NULL DEFAULT 'festival-crowd-v1',last_calculated_at timestamptz NOT NULL DEFAULT now(),version integer NOT NULL DEFAULT 1,CHECK(current_crowd<=stage_capacity),UNIQUE(runtime_day_id,runtime_stage_id));
CREATE TABLE public.festival_runtime_crowd_movements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),runtime_session_id uuid NOT NULL REFERENCES public.festival_runtime_sessions(id),runtime_day_id uuid NOT NULL REFERENCES public.festival_runtime_days(id),from_stage_id uuid REFERENCES public.festival_runtime_stages(id),to_stage_id uuid REFERENCES public.festival_runtime_stages(id),arrivals integer NOT NULL DEFAULT 0,departures integer NOT NULL DEFAULT 0,reason text NOT NULL,calculation_key text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(runtime_session_id,calculation_key));
CREATE TABLE public.festival_runtime_incidents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),runtime_session_id uuid NOT NULL REFERENCES public.festival_runtime_sessions(id),runtime_day_id uuid REFERENCES public.festival_runtime_days(id),runtime_stage_id uuid REFERENCES public.festival_runtime_stages(id),category text NOT NULL CHECK(category IN('medical','security','crowd','weather','technical','power','stage','artist','staffing','supplier','transport','food_safety','fire_safety')),incident_type text NOT NULL,severity text NOT NULL CHECK(severity IN('minor','moderate','major','critical')),seed text NOT NULL,trigger text NOT NULL,status text NOT NULL DEFAULT 'detected' CHECK(status IN('detected','acknowledged','assigned','contained','resolved','escalated','handed_over')),required_response text NOT NULL,public_safe_summary text NOT NULL,private_operational_details text NOT NULL,formula_version text NOT NULL DEFAULT 'festival-incident-v1',resolution_outcome text CHECK(resolution_outcome IN('resolved_quickly','resolved','contained','delayed_resolution','escalated','stage_paused','festival_paused')),detected_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz,version integer NOT NULL DEFAULT 1,dedupe_key text NOT NULL,UNIQUE(runtime_session_id,dedupe_key));
CREATE TABLE public.festival_runtime_incident_actions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),incident_id uuid NOT NULL REFERENCES public.festival_runtime_incidents(id),actor_profile_id uuid NOT NULL REFERENCES public.profiles(id),action text NOT NULL,authority_scope text NOT NULL,response_department text,notes text,expected_version integer NOT NULL,idempotency_key uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(incident_id,idempotency_key));
CREATE TABLE public.festival_runtime_incident_outcomes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),incident_id uuid UNIQUE NOT NULL REFERENCES public.festival_runtime_incidents(id),outcome text NOT NULL,response_quality integer NOT NULL CHECK(response_quality BETWEEN 0 AND 100),response_seconds integer NOT NULL DEFAULT 0,staff_coverage integer NOT NULL DEFAULT 0,equipment_score integer NOT NULL DEFAULT 0,operational_effects jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.festival_runtime_staff_outcomes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),runtime_session_id uuid NOT NULL REFERENCES public.festival_runtime_sessions(id),staff_checkin_id uuid UNIQUE NOT NULL REFERENCES public.festival_runtime_staff_checkins(id),source_type text NOT NULL CHECK(source_type IN('player','npc')),attendance_score integer NOT NULL,lateness_minutes integer NOT NULL DEFAULT 0,shift_completion integer NOT NULL,workload integer NOT NULL,qualification_match integer NOT NULL,department_coverage integer NOT NULL,incident_response integer NOT NULL,role_effectiveness integer NOT NULL,preliminary_score integer NOT NULL,formula_version text NOT NULL DEFAULT 'festival-staff-v1',captured_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.festival_runtime_supplier_outcomes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),runtime_session_id uuid NOT NULL REFERENCES public.festival_runtime_sessions(id),supplier_checkin_id uuid UNIQUE NOT NULL REFERENCES public.festival_runtime_supplier_checkins(id),arrival_status text NOT NULL,lateness_minutes integer NOT NULL DEFAULT 0,delivery_completeness integer NOT NULL,product_quality integer NOT NULL,service_quality integer NOT NULL,reliability integer NOT NULL,contract_compliance integer NOT NULL,operational_impact jsonb NOT NULL DEFAULT '{}',formula_version text NOT NULL DEFAULT 'festival-supplier-v1',captured_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.festival_runtime_sponsor_activations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),runtime_session_id uuid NOT NULL REFERENCES public.festival_runtime_sessions(id),source_activation_id uuid,contract_deliverable_id uuid,activation_type text NOT NULL,placement text NOT NULL,status text NOT NULL DEFAULT 'planned' CHECK(status IN('planned','ready','active','completed','partially_completed','failed','cancelled')),starts_at timestamptz,ends_at timestamptz,actual_start timestamptz,actual_end timestamptz,audience_exposure integer NOT NULL DEFAULT 0,delivery_quality integer,staff_support integer,operational_issues jsonb NOT NULL DEFAULT '[]',public_visibility boolean NOT NULL DEFAULT true,version integer NOT NULL DEFAULT 1,UNIQUE(runtime_session_id,source_activation_id));
CREATE TABLE public.festival_runtime_vendor_sales(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),runtime_session_id uuid NOT NULL REFERENCES public.festival_runtime_sessions(id),runtime_day_id uuid NOT NULL REFERENCES public.festival_runtime_days(id),category text NOT NULL CHECK(category IN('food','soft_drinks','alcohol_where_game_rules_allow','festival_merch','artist_merch')),product_id uuid,product_name text NOT NULL,currency_code text NOT NULL CHECK(currency_code~'^[A-Z]{3}$'),opening_stock integer NOT NULL CHECK(opening_stock>=0),remaining_stock integer NOT NULL CHECK(remaining_stock>=0),unit_price_minor bigint NOT NULL CHECK(unit_price_minor>=0),units_sold integer NOT NULL DEFAULT 0,gross_revenue_minor bigint NOT NULL DEFAULT 0,tax_liability_minor bigint NOT NULL DEFAULT 0,cost_basis_minor bigint NOT NULL DEFAULT 0,waste_units integer NOT NULL DEFAULT 0,sold_out boolean NOT NULL DEFAULT false,status text NOT NULL DEFAULT 'open' CHECK(status IN('open','closed')),formula_version text NOT NULL DEFAULT 'festival-vendor-v1',version integer NOT NULL DEFAULT 1,CHECK(units_sold+waste_units+remaining_stock=opening_stock));
CREATE TABLE public.festival_runtime_revenue_postings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),vendor_sales_id uuid NOT NULL REFERENCES public.festival_runtime_vendor_sales(id),posting_key text UNIQUE NOT NULL,amount_minor bigint NOT NULL,currency_code text NOT NULL,canonical_transaction_id uuid,liabilities jsonb NOT NULL DEFAULT '{}',posted_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.festival_runtime_outcome_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),runtime_session_id uuid UNIQUE NOT NULL REFERENCES public.festival_runtime_sessions(id),snapshot jsonb NOT NULL,engine_version text NOT NULL,formula_versions jsonb NOT NULL,content_digest text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());

CREATE FUNCTION public._festival_incident_authorised(p_incident uuid,p_actor uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT public._festival_runtime_owner(i.runtime_session_id,p_actor) OR EXISTS(SELECT 1 FROM public.festival_stage_manager_assignments m JOIN public.festival_runtime_sessions r ON r.id=i.runtime_session_id JOIN public.festival_launches l ON l.id=r.festival_launch_id WHERE i.id=p_incident AND i.runtime_stage_id IS NOT NULL AND m.festival_timetable_plan_id=l.timetable_plan_id AND m.stage_id=(SELECT source_stage_id FROM public.festival_runtime_stages WHERE id=i.runtime_stage_id) AND m.profile_id=p_actor AND m.status='assigned') FROM public.festival_runtime_incidents i WHERE i.id=p_incident$$;

CREATE FUNCTION public.recalculate_festival_crowds(p_runtime_session_id uuid,p_runtime_day_id uuid,p_expected_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE r public.festival_runtime_sessions%ROWTYPE;a integer; total_weight numeric; allocated integer:=0; c record; old integer; target integer; calc text; weather_factor numeric:=1;
BEGIN SELECT * INTO r FROM public.festival_runtime_sessions WHERE id=p_runtime_session_id FOR UPDATE;IF NOT public._festival_runtime_owner(r.id,public._festival_runtime_actor()) THEN RAISE EXCEPTION 'festival_runtime_forbidden';END IF;IF r.version<>p_expected_version THEN RAISE EXCEPTION 'festival_runtime_stale';END IF;SELECT onsite_count INTO a FROM public.festival_runtime_attendance WHERE runtime_day_id=p_runtime_day_id;SELECT CASE weather_state WHEN 'storm' THEN .55 WHEN 'heavy_rain' THEN .72 WHEN 'high_wind' THEN .82 ELSE 1 END INTO weather_factor FROM public.festival_runtime_weather WHERE runtime_day_id=p_runtime_day_id;weather_factor:=coalesce(weather_factor,1);calc:=p_runtime_day_id||':'||p_expected_version;
SELECT coalesce(sum((50+(get_byte(decode(substr(md5(st.stage_seed||coalesce(p.id::text,'')),1,2),'hex'),0)%51)+CASE WHEN p.status='live' THEN 35 ELSE 0 END-LEAST(p.delay_minutes,30))*weather_factor),1) INTO total_weight FROM public.festival_runtime_stages st LEFT JOIN LATERAL(SELECT * FROM public.festival_runtime_performances x WHERE x.runtime_stage_id=st.id AND x.runtime_day_id=p_runtime_day_id AND x.status IN('live','starting','ready','delayed') ORDER BY x.scheduled_start LIMIT 1)p ON true WHERE st.runtime_session_id=r.id AND st.status NOT IN('closed','failed');
FOR c IN SELECT st.*,p.id performance_id,(50+(get_byte(decode(substr(md5(st.stage_seed||coalesce(p.id::text,'')),1,2),'hex'),0)%51)+CASE WHEN p.status='live' THEN 35 ELSE 0 END-LEAST(coalesce(p.delay_minutes,0),30))*weather_factor weight FROM public.festival_runtime_stages st LEFT JOIN LATERAL(SELECT * FROM public.festival_runtime_performances x WHERE x.runtime_stage_id=st.id AND x.runtime_day_id=p_runtime_day_id AND x.status IN('live','starting','ready','delayed') ORDER BY x.scheduled_start LIMIT 1)p ON true WHERE st.runtime_session_id=r.id AND st.status NOT IN('closed','failed') ORDER BY st.id LOOP target:=least(c.capacity,greatest(0,round(a*c.weight/total_weight)));SELECT current_crowd INTO old FROM public.festival_runtime_stage_crowds WHERE runtime_day_id=p_runtime_day_id AND runtime_stage_id=c.id;old:=coalesce(old,0);INSERT INTO public.festival_runtime_stage_crowds(runtime_session_id,runtime_day_id,runtime_stage_id,runtime_performance_id,current_crowd,stage_capacity,crowd_share,arrivals,departures,queue_size,safety_pressure,peak_audience,audience_total,sample_count,seed,last_calculated_at)VALUES(r.id,p_runtime_day_id,c.id,c.performance_id,target,c.capacity,CASE WHEN a=0 THEN 0 ELSE target::numeric/a END,greatest(target-old,0),greatest(old-target,0),greatest(round(a*c.weight/total_weight)-c.capacity,0),least(100,round(target::numeric/nullif(c.capacity,0)*100)),target,target,1,encode(digest(r.runtime_seed||':crowd:'||p_runtime_day_id||':'||c.id,'sha256'),'hex'),now()) ON CONFLICT(runtime_day_id,runtime_stage_id) DO UPDATE SET runtime_performance_id=excluded.runtime_performance_id,current_crowd=excluded.current_crowd,crowd_share=excluded.crowd_share,arrivals=excluded.arrivals,departures=excluded.departures,queue_size=excluded.queue_size,safety_pressure=excluded.safety_pressure,peak_audience=greatest(festival_runtime_stage_crowds.peak_audience,excluded.current_crowd),audience_total=festival_runtime_stage_crowds.audience_total+excluded.current_crowd,sample_count=festival_runtime_stage_crowds.sample_count+1,last_calculated_at=now(),version=festival_runtime_stage_crowds.version+1;INSERT INTO public.festival_runtime_crowd_movements(runtime_session_id,runtime_day_id,to_stage_id,arrivals,departures,reason,calculation_key)VALUES(r.id,p_runtime_day_id,c.id,greatest(target-old,0),greatest(old-target,0),'deterministic_distribution',calc||':'||c.id) ON CONFLICT DO NOTHING;allocated:=allocated+target;END LOOP;
INSERT INTO public.festival_runtime_crowds(runtime_session_id,runtime_day_id,admitted_count,allocated_count,unallocated_count,seed)VALUES(r.id,p_runtime_day_id,a,allocated,greatest(a-allocated,0),encode(digest(r.runtime_seed||':crowd:'||p_runtime_day_id,'sha256'),'hex')) ON CONFLICT(runtime_day_id) DO UPDATE SET admitted_count=excluded.admitted_count,allocated_count=excluded.allocated_count,unallocated_count=excluded.unallocated_count,last_calculated_at=now(),version=festival_runtime_crowds.version+1;RETURN jsonb_build_object('runtimeSessionId',r.id,'allocated',allocated,'unallocated',greatest(a-allocated,0),'idempotencyKey',p_idempotency_key);END$$;

CREATE FUNCTION public._festival_incident_action(p_incident uuid,p_expected integer,p_key uuid,p_action text,p_status text,p_department text DEFAULT NULL,p_outcome text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE i public.festival_runtime_incidents%ROWTYPE;a uuid:=public._festival_runtime_actor();BEGIN SELECT * INTO i FROM public.festival_runtime_incidents WHERE id=p_incident FOR UPDATE;IF NOT public._festival_incident_authorised(i.id,a) THEN RAISE EXCEPTION 'festival_incident_forbidden';END IF;IF i.version<>p_expected THEN RAISE EXCEPTION 'festival_incident_stale';END IF;INSERT INTO public.festival_runtime_incident_actions(incident_id,actor_profile_id,action,authority_scope,response_department,expected_version,idempotency_key)VALUES(i.id,a,p_action,CASE WHEN public._festival_runtime_owner(i.runtime_session_id,a) THEN 'festival' ELSE 'assigned_stage' END,p_department,p_expected,p_key) ON CONFLICT(incident_id,idempotency_key) DO NOTHING;IF NOT FOUND THEN RETURN jsonb_build_object('id',i.id,'status',i.status,'version',i.version,'idempotent',true);END IF;UPDATE public.festival_runtime_incidents SET status=p_status,resolution_outcome=coalesce(p_outcome,resolution_outcome),resolved_at=CASE WHEN p_status IN('resolved','handed_over') THEN now() END,version=version+1 WHERE id=i.id RETURNING * INTO i;PERFORM public._festival_runtime_event(i.runtime_session_id,'incident_'||p_action,i.id,jsonb_build_object('message',i.public_safe_summary,'status',i.status),jsonb_build_object('category',i.category,'department',p_department),'incident-action:'||p_key);RETURN jsonb_build_object('id',i.id,'status',i.status,'version',i.version,'idempotent',false);END$$;
CREATE FUNCTION public.acknowledge_festival_incident(p_incident_id uuid,p_expected_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$SELECT public._festival_incident_action(p_incident_id,p_expected_version,p_idempotency_key,'acknowledge','acknowledged')$$;
CREATE FUNCTION public.assign_festival_incident_response(p_incident_id uuid,p_expected_version integer,p_department text,p_idempotency_key uuid) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$SELECT public._festival_incident_action(p_incident_id,p_expected_version,p_idempotency_key,'assign','assigned',p_department)$$;
CREATE FUNCTION public.resolve_festival_incident(p_incident_id uuid,p_expected_version integer,p_outcome text,p_idempotency_key uuid) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$SELECT public._festival_incident_action(p_incident_id,p_expected_version,p_idempotency_key,'resolve','resolved',NULL,p_outcome)$$;
CREATE FUNCTION public.escalate_festival_incident(p_incident_id uuid,p_expected_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$SELECT public._festival_incident_action(p_incident_id,p_expected_version,p_idempotency_key,'escalate','escalated')$$;
CREATE FUNCTION public.close_festival_stage_for_incident(p_incident_id uuid,p_expected_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE x jsonb;i public.festival_runtime_incidents%ROWTYPE;BEGIN x:=public._festival_incident_action(p_incident_id,p_expected_version,p_idempotency_key,'close_stage','contained',NULL,'stage_paused');SELECT * INTO i FROM public.festival_runtime_incidents WHERE id=p_incident_id;UPDATE public.festival_runtime_stages SET status='paused',version=version+1 WHERE id=i.runtime_stage_id AND status<>'failed';RETURN x;END$$;
CREATE FUNCTION public.reopen_festival_stage_after_incident(p_incident_id uuid,p_expected_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE x jsonb;i public.festival_runtime_incidents%ROWTYPE;BEGIN x:=public._festival_incident_action(p_incident_id,p_expected_version,p_idempotency_key,'reopen_stage','resolved',NULL,'resolved');SELECT * INTO i FROM public.festival_runtime_incidents WHERE id=p_incident_id;UPDATE public.festival_runtime_stages SET status='ready',version=version+1 WHERE id=i.runtime_stage_id AND status='paused';RETURN x;END$$;

CREATE FUNCTION public.start_festival_sponsor_activation(p_activation_id uuid,p_expected_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE x public.festival_runtime_sponsor_activations%ROWTYPE;BEGIN SELECT * INTO x FROM public.festival_runtime_sponsor_activations WHERE id=p_activation_id FOR UPDATE;IF NOT public._festival_runtime_owner(x.runtime_session_id,public._festival_runtime_actor()) THEN RAISE EXCEPTION 'festival_runtime_forbidden';END IF;IF x.version<>p_expected_version THEN RAISE EXCEPTION 'festival_runtime_stale';END IF;UPDATE public.festival_runtime_sponsor_activations SET status='active',actual_start=now(),version=version+1 WHERE id=x.id AND status IN('planned','ready') RETURNING * INTO x;IF x.id IS NULL THEN RAISE EXCEPTION 'festival_sponsor_activation_invalid';END IF;PERFORM public._festival_runtime_event(x.runtime_session_id,'sponsor_activation_started',x.id,CASE WHEN x.public_visibility THEN jsonb_build_object('message','A Festival partner activation is now live.') ELSE '{}' END,'{}','sponsor-start:'||p_idempotency_key);RETURN to_jsonb(x);END$$;
CREATE FUNCTION public.complete_festival_sponsor_activation(p_activation_id uuid,p_expected_version integer,p_status text,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE x public.festival_runtime_sponsor_activations%ROWTYPE;BEGIN SELECT * INTO x FROM public.festival_runtime_sponsor_activations WHERE id=p_activation_id FOR UPDATE;IF NOT public._festival_runtime_owner(x.runtime_session_id,public._festival_runtime_actor()) OR p_status NOT IN('completed','partially_completed','failed','cancelled') THEN RAISE EXCEPTION 'festival_runtime_forbidden';END IF;IF x.version<>p_expected_version THEN RAISE EXCEPTION 'festival_runtime_stale';END IF;UPDATE public.festival_runtime_sponsor_activations SET status=p_status,actual_end=now(),version=version+1 WHERE id=x.id RETURNING * INTO x;RETURN to_jsonb(x);END$$;
CREATE FUNCTION public.close_festival_vendor_sales(p_vendor_sales_id uuid,p_expected_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE x public.festival_runtime_vendor_sales%ROWTYPE;BEGIN SELECT * INTO x FROM public.festival_runtime_vendor_sales WHERE id=p_vendor_sales_id FOR UPDATE;IF NOT public._festival_runtime_owner(x.runtime_session_id,public._festival_runtime_actor()) THEN RAISE EXCEPTION 'festival_runtime_forbidden';END IF;IF x.version<>p_expected_version THEN RAISE EXCEPTION 'festival_runtime_stale';END IF;UPDATE public.festival_runtime_vendor_sales SET status='closed',version=version+1 WHERE id=x.id RETURNING * INTO x;INSERT INTO public.festival_runtime_revenue_postings(vendor_sales_id,posting_key,amount_minor,currency_code,liabilities)VALUES(x.id,'vendor-close:'||x.id,x.gross_revenue_minor,x.currency_code,jsonb_build_object('taxLiabilityMinor',x.tax_liability_minor,'artistMerchRoyaltyDeferred',x.category='artist_merch')) ON CONFLICT(posting_key) DO NOTHING;RETURN to_jsonb(x)||jsonb_build_object('idempotencyKey',p_idempotency_key);END$$;

CREATE FUNCTION public.get_festival_crowd_runtime(p_runtime_session_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT CASE WHEN public._festival_runtime_owner(p_runtime_session_id,public._festival_runtime_actor()) THEN jsonb_build_object('crowds',(SELECT coalesce(jsonb_agg(to_jsonb(c)),'[]') FROM public.festival_runtime_crowds c WHERE c.runtime_session_id=p_runtime_session_id),'stages',(SELECT coalesce(jsonb_agg(to_jsonb(c)),'[]') FROM public.festival_runtime_stage_crowds c WHERE c.runtime_session_id=p_runtime_session_id),'weather',(SELECT coalesce(jsonb_agg(to_jsonb(w)),'[]') FROM public.festival_runtime_weather w WHERE w.runtime_session_id=p_runtime_session_id)) END$$;
CREATE FUNCTION public.get_festival_incident_dashboard(p_runtime_session_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT CASE WHEN public._festival_runtime_owner(p_runtime_session_id,public._festival_runtime_actor()) THEN jsonb_build_object('incidents',(SELECT coalesce(jsonb_agg(to_jsonb(i) ORDER BY i.detected_at DESC),'[]') FROM public.festival_runtime_incidents i WHERE i.runtime_session_id=p_runtime_session_id),'outcomes',(SELECT coalesce(jsonb_agg(to_jsonb(o)),'[]') FROM public.festival_runtime_incident_outcomes o JOIN public.festival_runtime_incidents i ON i.id=o.incident_id WHERE i.runtime_session_id=p_runtime_session_id)) END$$;
CREATE FUNCTION public.get_festival_operational_outcomes(p_runtime_session_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT CASE WHEN public._festival_runtime_owner(p_runtime_session_id,public._festival_runtime_actor()) THEN jsonb_build_object('staff',(SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') FROM public.festival_runtime_staff_outcomes x WHERE x.runtime_session_id=p_runtime_session_id),'suppliers',(SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') FROM public.festival_runtime_supplier_outcomes x WHERE x.runtime_session_id=p_runtime_session_id),'snapshot',(SELECT snapshot FROM public.festival_runtime_outcome_snapshots WHERE runtime_session_id=p_runtime_session_id)) END$$;
CREATE FUNCTION public.get_festival_vendor_sales(p_runtime_session_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') FROM public.festival_runtime_vendor_sales x WHERE x.runtime_session_id=p_runtime_session_id AND public._festival_runtime_owner(x.runtime_session_id,public._festival_runtime_actor())$$;
CREATE FUNCTION public.get_festival_sponsor_activation_runtime(p_runtime_session_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') FROM public.festival_runtime_sponsor_activations x WHERE x.runtime_session_id=p_runtime_session_id AND public._festival_runtime_owner(x.runtime_session_id,public._festival_runtime_actor())$$;
CREATE FUNCTION public.get_public_festival_live_experience(p_public_slug text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT public.get_public_festival_live_status(p_public_slug)||jsonb_build_object('weather',(SELECT jsonb_build_object('state',w.weather_state,'groundCondition',w.ground_condition) FROM public.festival_runtime_weather w JOIN public.festival_runtime_days d ON d.id=w.runtime_day_id WHERE w.runtime_session_id=r.id ORDER BY abs(d.festival_date-current_date) LIMIT 1),'stageCrowds',(SELECT coalesce(jsonb_agg(jsonb_build_object('stageId',c.runtime_stage_id,'stageName',s.stage_name,'crowdBand',CASE WHEN c.current_crowd>=c.stage_capacity THEN 'full' WHEN c.current_crowd>=c.stage_capacity*.9 THEN 'near_capacity' WHEN c.current_crowd>=c.stage_capacity*.7 THEN 'very_busy' WHEN c.current_crowd>=c.stage_capacity*.4 THEN 'busy' WHEN c.current_crowd>=c.stage_capacity*.15 THEN 'building' ELSE 'quiet' END,'mood',c.mood,'stageStatus',s.status)),'[]') FROM public.festival_runtime_stage_crowds c JOIN public.festival_runtime_stages s ON s.id=c.runtime_stage_id WHERE c.runtime_session_id=r.id),'incidents',(SELECT coalesce(jsonb_agg(jsonb_build_object('message',i.public_safe_summary,'severity',i.severity)),'[]') FROM public.festival_runtime_incidents i WHERE i.runtime_session_id=r.id AND i.status NOT IN('resolved','handed_over')),'sponsors',(SELECT coalesce(jsonb_agg(jsonb_build_object('type',x.activation_type,'placement',x.placement,'status',x.status)),'[]') FROM public.festival_runtime_sponsor_activations x WHERE x.runtime_session_id=r.id AND x.public_visibility),'availability',(SELECT coalesce(jsonb_agg(jsonb_build_object('category',v.category,'available',v.remaining_stock>0)),'[]') FROM public.festival_runtime_vendor_sales v WHERE v.runtime_session_id=r.id AND v.status='open')) FROM public.festival_runtime_sessions r JOIN public.festival_public_editions e ON e.festival_launch_id=r.festival_launch_id WHERE e.slug=p_public_slug$$;

CREATE FUNCTION public.finalise_festival_runtime_outcomes(p_runtime_session_id uuid,p_expected_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE r public.festival_runtime_sessions%ROWTYPE;s jsonb;d text;BEGIN SELECT * INTO r FROM public.festival_runtime_sessions WHERE id=p_runtime_session_id FOR UPDATE;IF NOT public._festival_runtime_owner(r.id,public._festival_runtime_actor()) THEN RAISE EXCEPTION 'festival_runtime_forbidden';END IF;IF r.version<>p_expected_version THEN RAISE EXCEPTION 'festival_runtime_stale';END IF;IF EXISTS(SELECT 1 FROM public.festival_runtime_days WHERE runtime_session_id=r.id AND status NOT IN('completed','cancelled')) OR EXISTS(SELECT 1 FROM public.festival_runtime_performances WHERE runtime_session_id=r.id AND status NOT IN('completed','cancelled','abandoned','failed')) OR r.gates_open OR r.status NOT IN('public_closed','site_clearance','runtime_complete') OR EXISTS(SELECT 1 FROM public.festival_runtime_incidents WHERE runtime_session_id=r.id AND status NOT IN('resolved','handed_over')) OR EXISTS(SELECT 1 FROM public.festival_runtime_sponsor_activations WHERE runtime_session_id=r.id AND status IN('planned','ready','active')) OR EXISTS(SELECT 1 FROM public.festival_runtime_vendor_sales WHERE runtime_session_id=r.id AND status='open') OR EXISTS(SELECT 1 FROM public.festival_runtime_staff_checkins WHERE runtime_session_id=r.id AND status IN('expected','checked_in','late')) OR EXISTS(SELECT 1 FROM public.festival_runtime_supplier_checkins c WHERE c.runtime_session_id=r.id AND NOT EXISTS(SELECT 1 FROM public.festival_runtime_supplier_outcomes o WHERE o.supplier_checkin_id=c.id)) THEN RAISE EXCEPTION 'festival_runtime_outcomes_blocked';END IF;s:=jsonb_build_object('attendance',(SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') FROM public.festival_runtime_attendance x WHERE x.runtime_session_id=r.id),'performances',(SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') FROM public.festival_runtime_performances x WHERE x.runtime_session_id=r.id),'crowds',(SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') FROM public.festival_runtime_stage_crowds x WHERE x.runtime_session_id=r.id),'weather',(SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') FROM public.festival_runtime_weather x WHERE x.runtime_session_id=r.id),'incidents',(SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') FROM public.festival_runtime_incidents x WHERE x.runtime_session_id=r.id),'staffOutcomes',(SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') FROM public.festival_runtime_staff_outcomes x WHERE x.runtime_session_id=r.id),'supplierOutcomes',(SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') FROM public.festival_runtime_supplier_outcomes x WHERE x.runtime_session_id=r.id),'sponsorActivations',(SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') FROM public.festival_runtime_sponsor_activations x WHERE x.runtime_session_id=r.id),'vendorSales',(SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') FROM public.festival_runtime_vendor_sales x WHERE x.runtime_session_id=r.id),'runtimeEvents',(SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') FROM public.festival_runtime_events x WHERE x.runtime_session_id=r.id));d:=encode(digest(s::text,'sha256'),'hex');INSERT INTO public.festival_runtime_outcome_snapshots(runtime_session_id,snapshot,engine_version,formula_versions,content_digest)VALUES(r.id,s,r.engine_version,jsonb_build_object('runtime',r.formula_version,'crowd','festival-crowd-v1','incidents','festival-incident-v1','vendors','festival-vendor-v1'),d) ON CONFLICT(runtime_session_id) DO NOTHING;UPDATE public.festival_runtime_sessions SET status='runtime_complete',ready_for_settlement=true,completed_at=coalesce(completed_at,now()),version=version+1 WHERE id=r.id RETURNING * INTO r;RETURN public._festival_runtime_receipt(r)||jsonb_build_object('readyForSettlement',true,'outcomeDigest',d,'idempotencyKey',p_idempotency_key);END$$;

DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['festival_runtime_weather','festival_runtime_crowds','festival_runtime_stage_crowds','festival_runtime_crowd_movements','festival_runtime_incidents','festival_runtime_incident_actions','festival_runtime_incident_outcomes','festival_runtime_staff_outcomes','festival_runtime_supplier_outcomes','festival_runtime_sponsor_activations','festival_runtime_vendor_sales','festival_runtime_revenue_postings','festival_runtime_outcome_snapshots'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON TABLE public.%I FROM PUBLIC,anon,authenticated',t);END LOOP;END$$;
REVOKE ALL ON FUNCTION public._festival_incident_authorised(uuid,uuid),public._festival_incident_action(uuid,integer,uuid,text,text,text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.get_public_festival_live_experience(text) TO anon,authenticated;
GRANT EXECUTE ON FUNCTION public.get_festival_crowd_runtime(uuid),public.get_festival_incident_dashboard(uuid),public.get_festival_operational_outcomes(uuid),public.get_festival_vendor_sales(uuid),public.get_festival_sponsor_activation_runtime(uuid),public.recalculate_festival_crowds(uuid,uuid,integer,uuid),public.acknowledge_festival_incident(uuid,integer,uuid),public.assign_festival_incident_response(uuid,integer,text,uuid),public.resolve_festival_incident(uuid,integer,text,uuid),public.escalate_festival_incident(uuid,integer,uuid),public.close_festival_stage_for_incident(uuid,integer,uuid),public.reopen_festival_stage_after_incident(uuid,integer,uuid),public.start_festival_sponsor_activation(uuid,integer,uuid),public.complete_festival_sponsor_activation(uuid,integer,text,uuid),public.close_festival_vendor_sales(uuid,integer,uuid),public.finalise_festival_runtime_outcomes(uuid,integer,uuid) TO authenticated;
COMMENT ON TABLE public.festival_runtime_outcome_snapshots IS 'Immutable Phase 8B operational source for Phase 9 settlement. UPDATE and DELETE remain revoked.';
COMMENT ON TABLE public.festival_runtime_revenue_postings IS 'Exactly-once runtime revenue boundary; tax and artist-merch liabilities remain deferred to Phase 9.';

-- Future runtimes receive deterministic operational seeds and retry-safe job rows.
CREATE FUNCTION public._seed_festival_runtime_operations() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE states text[]:=ARRAY['clear','cloudy','light_rain','heavy_rain','hot','cold','high_wind','storm'];pick integer;BEGIN pick:=get_byte(decode(substr(md5(NEW.day_seed),1,2),'hex'),0)%100;INSERT INTO public.festival_runtime_weather(runtime_session_id,runtime_day_id,weather_state,temperature_band,ground_condition,operational_impact,seed) VALUES(NEW.runtime_session_id,NEW.id,CASE WHEN pick<28 THEN 'clear' WHEN pick<50 THEN 'cloudy' WHEN pick<65 THEN 'light_rain' WHEN pick<74 THEN 'heavy_rain' WHEN pick<82 THEN 'hot' WHEN pick<89 THEN 'cold' WHEN pick<96 THEN 'high_wind' ELSE 'storm' END,CASE WHEN pick BETWEEN 74 AND 81 THEN 'hot' WHEN pick BETWEEN 82 AND 88 THEN 'cold' ELSE 'mild' END,CASE WHEN pick BETWEEN 65 AND 73 THEN 'muddy' WHEN pick>=96 THEN 'unsafe' WHEN pick BETWEEN 50 AND 64 THEN 'damp' ELSE 'normal' END,CASE WHEN pick>=96 THEN 95 WHEN pick BETWEEN 65 AND 73 THEN 65 WHEN pick BETWEEN 89 AND 95 THEN 70 ELSE 20 END,encode(digest(NEW.day_seed||':weather','sha256'),'hex')) ON CONFLICT(runtime_day_id) DO NOTHING;INSERT INTO public.festival_runtime_crowds(runtime_session_id,runtime_day_id,seed)VALUES(NEW.runtime_session_id,NEW.id,encode(digest(NEW.day_seed||':crowd','sha256'),'hex')) ON CONFLICT(runtime_day_id) DO NOTHING;INSERT INTO public.festival_runtime_jobs(runtime_session_id,runtime_day_id,job_type,run_at,dedupe_key) SELECT NEW.runtime_session_id,NEW.id,j.kind,NEW.starts_at,j.kind||':'||NEW.id FROM unnest(ARRAY['evaluate_weather','update_crowd_distribution','update_crowd_mood','evaluate_incidents','resolve_automatic_incidents','update_vendor_sales','update_sponsor_activations','evaluate_staff_outcomes','evaluate_supplier_outcomes','capture_live_snapshot'])j(kind) ON CONFLICT(runtime_session_id,dedupe_key) DO NOTHING;RETURN NEW;END$$;
CREATE TRIGGER seed_festival_runtime_operations AFTER INSERT ON public.festival_runtime_days FOR EACH ROW EXECUTE FUNCTION public._seed_festival_runtime_operations();

CREATE FUNCTION public._festival_performance_crowd_outcome() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE c public.festival_runtime_stage_crowds%ROWTYPE;score numeric;BEGIN IF NEW.status='completed' AND OLD.status IS DISTINCT FROM NEW.status THEN SELECT * INTO c FROM public.festival_runtime_stage_crowds WHERE runtime_day_id=NEW.runtime_day_id AND runtime_stage_id=NEW.runtime_stage_id;score:=coalesce(NEW.performance_score,50);UPDATE public.festival_runtime_stage_crowds SET mood=CASE WHEN score>=90 THEN 'ecstatic' WHEN score>=80 THEN 'jumping' WHEN score>=70 THEN 'excited' WHEN score>=60 THEN 'engaged' WHEN score>=45 THEN 'interested' WHEN score>=30 THEN 'calm' ELSE 'bored' END,energy=least(100,greatest(0,round(score))),satisfaction=least(100,greatest(0,round((score+coalesce(c.satisfaction,50))/2))),departures=CASE WHEN score<40 THEN round(coalesce(c.current_crowd,0)*.15) ELSE coalesce(c.departures,0) END,version=version+1,last_calculated_at=now() WHERE id=c.id;UPDATE public.festival_runtime_performances SET peak_audience=coalesce(c.peak_audience,0),average_audience=CASE WHEN coalesce(c.sample_count,0)=0 THEN coalesce(c.current_crowd,0) ELSE round(c.audience_total::numeric/c.sample_count) END,crowd_response_score=score,early_departures=CASE WHEN score<40 THEN round(coalesce(c.current_crowd,0)*.15) ELSE 0 END WHERE id=NEW.id;PERFORM public._festival_runtime_event(NEW.runtime_session_id,'performance_crowd_resolved',NEW.id,jsonb_build_object('message',CASE WHEN score>=70 THEN NEW.artist_name||' has the crowd buzzing.' ELSE 'The crowd is moving between stages.' END),jsonb_build_object('peakAudience',c.peak_audience,'crowdResponseScore',score),'performance-crowd:'||NEW.id);END IF;RETURN NEW;END$$;
CREATE TRIGGER festival_performance_crowd_outcome AFTER UPDATE OF status ON public.festival_runtime_performances FOR EACH ROW EXECUTE FUNCTION public._festival_performance_crowd_outcome();

-- Condition-based incident detection: deterministic thresholds, never free random chance.
CREATE FUNCTION public._evaluate_festival_runtime_incidents(p_runtime_session_id uuid,p_runtime_day_id uuid) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE c record;n integer:=0;w public.festival_runtime_weather%ROWTYPE;r public.festival_runtime_sessions%ROWTYPE;BEGIN SELECT * INTO r FROM public.festival_runtime_sessions WHERE id=p_runtime_session_id;SELECT * INTO w FROM public.festival_runtime_weather WHERE runtime_day_id=p_runtime_day_id;FOR c IN SELECT * FROM public.festival_runtime_stage_crowds WHERE runtime_day_id=p_runtime_day_id LOOP IF c.safety_pressure>=92 THEN INSERT INTO public.festival_runtime_incidents(runtime_session_id,runtime_day_id,runtime_stage_id,category,incident_type,severity,seed,trigger,required_response,public_safe_summary,private_operational_details,dedupe_key)VALUES(r.id,p_runtime_day_id,c.runtime_stage_id,'crowd','capacity_pressure',CASE WHEN c.safety_pressure>=100 THEN 'major' ELSE 'moderate' END,encode(digest(r.incident_seed||':crowd:'||c.runtime_stage_id,'sha256'),'hex'),'stage safety pressure threshold','security and crowd management response','Access to a stage is temporarily being managed.','Crowd pressure threshold exceeded; review ingress, egress and coverage.','crowd-pressure:'||p_runtime_day_id||':'||c.runtime_stage_id) ON CONFLICT DO NOTHING;IF FOUND THEN n:=n+1;END IF;END IF;END LOOP;IF w.weather_state IN('storm','heavy_rain','high_wind') AND w.operational_impact>=65 THEN INSERT INTO public.festival_runtime_incidents(runtime_session_id,runtime_day_id,category,incident_type,severity,seed,trigger,required_response,public_safe_summary,private_operational_details,dedupe_key)VALUES(r.id,p_runtime_day_id,'weather','severe_weather_hold',CASE WHEN w.weather_state='storm' THEN 'major' ELSE 'moderate' END,w.seed,'weather operational impact threshold','weather contingency assessment','Some Festival activity may be delayed due to weather.','Apply the published weather contingency and assess outdoor stages.','weather:'||p_runtime_day_id) ON CONFLICT DO NOTHING;IF FOUND THEN n:=n+1;END IF;END IF;RETURN n;END$$;
REVOKE ALL ON FUNCTION public._seed_festival_runtime_operations(),public._festival_performance_crowd_outcome(),public._evaluate_festival_runtime_incidents(uuid,uuid) FROM PUBLIC,anon,authenticated;
-- Phase 8A/8B correctness patch: server simulation jobs, immutable evidence, and exact crowds.
CREATE TABLE public.festival_performance_simulation_jobs (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 runtime_session_id uuid NOT NULL REFERENCES public.festival_runtime_sessions(id),
 runtime_day_id uuid NOT NULL REFERENCES public.festival_runtime_days(id),
 runtime_stage_id uuid NOT NULL REFERENCES public.festival_runtime_stages(id),
 runtime_performance_id uuid NOT NULL UNIQUE REFERENCES public.festival_runtime_performances(id),
 status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','processing','completed','failed','exhausted')),
 attempts integer NOT NULL DEFAULT 0 CHECK (attempts >= 0), max_attempts integer NOT NULL DEFAULT 5 CHECK (max_attempts > 0),
 seed text NOT NULL, engine_version text NOT NULL, input_digest text NOT NULL, output_digest text,
 locked_at timestamptz, locked_by text, next_attempt_at timestamptz NOT NULL DEFAULT now(), last_error text,
 created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz,
 CHECK ((status = 'completed') = (completed_at IS NOT NULL AND output_digest IS NOT NULL))
);
CREATE INDEX festival_performance_jobs_claim_idx ON public.festival_performance_simulation_jobs(next_attempt_at,created_at) WHERE status IN ('pending','failed');

CREATE TABLE public.festival_performance_simulation_results (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), runtime_performance_id uuid NOT NULL UNIQUE REFERENCES public.festival_runtime_performances(id),
 canonical_gig_result_id uuid, engine_version text NOT NULL, seed text NOT NULL, input_digest text NOT NULL, output_digest text NOT NULL UNIQUE,
 base_performance_score numeric NOT NULL CHECK(base_performance_score BETWEEN 0 AND 100), festival_modifiers jsonb NOT NULL,
 final_score numeric NOT NULL CHECK(final_score BETWEEN 0 AND 100), technical_score numeric NOT NULL CHECK(technical_score BETWEEN 0 AND 100),
 crowd_response jsonb NOT NULL, attendance integer NOT NULL CHECK(attendance >= 0), delay_impact numeric NOT NULL,
 weather_impact numeric NOT NULL, incident_impact numeric NOT NULL, setlist_item_outcomes jsonb NOT NULL DEFAULT '[]',
 stage_actions jsonb NOT NULL DEFAULT '[]', generated_highlights jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.festival_crowd_recalculation_requests (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), runtime_session_id uuid NOT NULL REFERENCES public.festival_runtime_sessions(id),
 runtime_day_id uuid NOT NULL REFERENCES public.festival_runtime_days(id), idempotency_key uuid NOT NULL,
 input_digest text NOT NULL, output_digest text, status text NOT NULL DEFAULT 'processing' CHECK(status IN('processing','completed','failed')),
 result jsonb, sample_time timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz,
 UNIQUE(runtime_session_id,runtime_day_id,idempotency_key), CHECK(status <> 'completed' OR (result IS NOT NULL AND output_digest IS NOT NULL AND completed_at IS NOT NULL))
);

ALTER TABLE public.festival_performance_simulation_jobs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.festival_performance_simulation_results ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.festival_crowd_recalculation_requests ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.festival_performance_simulation_jobs,public.festival_performance_simulation_results,public.festival_crowd_recalculation_requests FROM anon,authenticated;

CREATE FUNCTION public._festival_assert_runtime_chain(p_session uuid,p_day uuid DEFAULT NULL,p_stage uuid DEFAULT NULL,p_performance uuid DEFAULT NULL)
RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF NOT EXISTS (SELECT 1 FROM public.festival_runtime_sessions r JOIN public.festival_launches l ON l.id=r.festival_launch_id JOIN public.festival_companies c ON c.id=l.festival_company_id WHERE r.id=p_session) THEN RAISE EXCEPTION 'festival_runtime_chain_session'; END IF;
 IF p_day IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.festival_runtime_days d WHERE d.id=p_day AND d.runtime_session_id=p_session) THEN RAISE EXCEPTION 'festival_runtime_chain_day'; END IF;
 IF p_stage IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.festival_runtime_stages s WHERE s.id=p_stage AND s.runtime_session_id=p_session) THEN RAISE EXCEPTION 'festival_runtime_chain_stage'; END IF;
 IF p_performance IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.festival_runtime_performances p WHERE p.id=p_performance AND p.runtime_session_id=p_session AND (p_day IS NULL OR p.runtime_day_id=p_day) AND (p_stage IS NULL OR p.runtime_stage_id=p_stage)) THEN RAISE EXCEPTION 'festival_runtime_chain_performance'; END IF;
END$$;

CREATE FUNCTION public._festival_immutable_result() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$BEGIN RAISE EXCEPTION 'festival_performance_result_immutable'; END$$;
CREATE TRIGGER festival_performance_result_immutable BEFORE UPDATE OR DELETE ON public.festival_performance_simulation_results FOR EACH ROW EXECUTE FUNCTION public._festival_immutable_result();
CREATE FUNCTION public._festival_immutable_snapshot() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$BEGIN RAISE EXCEPTION 'festival_runtime_snapshot_immutable'; END$$;
CREATE TRIGGER festival_runtime_outcome_snapshot_immutable BEFORE UPDATE OR DELETE ON public.festival_runtime_outcome_snapshots FOR EACH ROW EXECUTE FUNCTION public._festival_immutable_snapshot();

-- Service-role worker primitives. SKIP LOCKED permits multiple workers without duplicate claims.
CREATE FUNCTION public.claim_festival_performance_simulation_job(p_worker text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE j public.festival_performance_simulation_jobs%ROWTYPE;
BEGIN
 SELECT * INTO j FROM public.festival_performance_simulation_jobs WHERE status IN('pending','failed') AND attempts<max_attempts AND next_attempt_at<=now() ORDER BY next_attempt_at,id FOR UPDATE SKIP LOCKED LIMIT 1;
 IF j.id IS NULL THEN RETURN NULL; END IF;
 UPDATE public.festival_performance_simulation_jobs SET status='processing',attempts=attempts+1,locked_at=now(),locked_by=p_worker WHERE id=j.id RETURNING * INTO j;
 RETURN to_jsonb(j);
END$$;
REVOKE ALL ON FUNCTION public.claim_festival_performance_simulation_job(text) FROM PUBLIC,anon,authenticated;

CREATE FUNCTION public.complete_festival_performance_simulation_job(p_job uuid,p_worker text,p_input_digest text,p_output jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE j public.festival_performance_simulation_jobs%ROWTYPE; d text; r public.festival_performance_simulation_results%ROWTYPE;
BEGIN
 SELECT * INTO j FROM public.festival_performance_simulation_jobs WHERE id=p_job FOR UPDATE;
 IF j.id IS NULL OR j.status<>'processing' OR j.locked_by IS DISTINCT FROM p_worker THEN RAISE EXCEPTION 'festival_simulation_job_not_claimed'; END IF;
 IF j.input_digest<>p_input_digest THEN RAISE EXCEPTION 'festival_simulation_input_digest_mismatch'; END IF;
 d:=encode(digest(p_output::text,'sha256'),'hex');
 INSERT INTO public.festival_performance_simulation_results(runtime_performance_id,canonical_gig_result_id,engine_version,seed,input_digest,output_digest,base_performance_score,festival_modifiers,final_score,technical_score,crowd_response,attendance,delay_impact,weather_impact,incident_impact,setlist_item_outcomes,stage_actions,generated_highlights)
 VALUES(j.runtime_performance_id,(p_output->>'canonicalGigResultId')::uuid,j.engine_version,j.seed,j.input_digest,d,(p_output->>'basePerformanceScore')::numeric,p_output->'festivalModifiers',(p_output->>'finalScore')::numeric,(p_output->>'technicalScore')::numeric,p_output->'crowdResponse',(p_output->>'attendance')::integer,(p_output->>'delayImpact')::numeric,(p_output->>'weatherImpact')::numeric,(p_output->>'incidentImpact')::numeric,coalesce(p_output->'setlistItemOutcomes','[]'),coalesce(p_output->'stageActions','[]'),coalesce(p_output->'generatedHighlights','[]'))
 ON CONFLICT(runtime_performance_id) DO NOTHING RETURNING * INTO r;
 IF r.id IS NULL THEN SELECT * INTO r FROM public.festival_performance_simulation_results WHERE runtime_performance_id=j.runtime_performance_id; IF r.input_digest<>j.input_digest OR r.output_digest<>d THEN RAISE EXCEPTION 'festival_simulation_result_conflict'; END IF; END IF;
 UPDATE public.festival_runtime_performances SET engine_result_snapshot=p_output,performance_score=r.final_score,technical_score=r.technical_score,crowd_response=r.crowd_response::text,estimated_audience=r.attendance,status='completed',actual_end=coalesce(actual_end,now()),version=version+1 WHERE id=j.runtime_performance_id AND engine_result_snapshot IS NULL;
 UPDATE public.festival_performance_simulation_jobs SET status='completed',output_digest=d,completed_at=now(),locked_at=NULL,locked_by=NULL WHERE id=j.id;
 RETURN to_jsonb(r);
END$$;
REVOKE ALL ON FUNCTION public.complete_festival_performance_simulation_job(uuid,text,text,jsonb) FROM PUBLIC,anon,authenticated;

CREATE FUNCTION public.get_festival_performance_simulation_jobs(p_runtime_session_id uuid) RETURNS SETOF public.festival_performance_simulation_jobs LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF NOT public._festival_runtime_owner(p_runtime_session_id,public._festival_runtime_actor()) THEN RAISE EXCEPTION 'festival_runtime_forbidden'; END IF;
 RETURN QUERY SELECT j.* FROM public.festival_performance_simulation_jobs j WHERE j.runtime_session_id=p_runtime_session_id ORDER BY j.created_at,j.id;
END$$;

CREATE OR REPLACE FUNCTION public.resolve_festival_performance(p_runtime_performance_id uuid,p_expected_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE p public.festival_runtime_performances%ROWTYPE; j public.festival_performance_simulation_jobs%ROWTYPE; digest_input text;
BEGIN
 SELECT * INTO p FROM public.festival_runtime_performances WHERE id=p_runtime_performance_id FOR UPDATE;
 IF p.id IS NULL THEN RAISE EXCEPTION 'festival_runtime_chain_performance'; END IF;
 PERFORM public._festival_assert_runtime_chain(p.runtime_session_id,p.runtime_day_id,p.runtime_stage_id,p.id);
 IF NOT public._festival_runtime_owner(p.runtime_session_id,public._festival_runtime_actor()) THEN RAISE EXCEPTION 'festival_runtime_forbidden'; END IF;
 IF p.version<>p_expected_version THEN RAISE EXCEPTION 'festival_runtime_stale'; END IF;
 IF p.status='completed' THEN RETURN to_jsonb(p); END IF;
 IF p.status<>'live' OR p.engine_input_snapshot IS NULL THEN RAISE EXCEPTION 'festival_performance_resolution_invalid'; END IF;
 digest_input:=encode(digest(p.engine_input_snapshot::text,'sha256'),'hex');
 INSERT INTO public.festival_performance_simulation_jobs(runtime_session_id,runtime_day_id,runtime_stage_id,runtime_performance_id,seed,engine_version,input_digest)
 VALUES(p.runtime_session_id,p.runtime_day_id,p.runtime_stage_id,p.id,p.performance_seed,p.engine_version,digest_input) ON CONFLICT(runtime_performance_id) DO NOTHING RETURNING * INTO j;
 IF j.id IS NULL THEN SELECT * INTO j FROM public.festival_performance_simulation_jobs WHERE runtime_performance_id=p.id; IF j.input_digest<>digest_input THEN RAISE EXCEPTION 'festival_simulation_input_digest_mismatch'; END IF; END IF;
 RETURN jsonb_build_object('runtimePerformanceId',p.id,'simulationJobId',j.id,'simulationStatus',j.status,'idempotencyKey',p_idempotency_key);
END$$;

CREATE OR REPLACE FUNCTION public.recalculate_festival_crowds(p_runtime_session_id uuid,p_runtime_day_id uuid,p_expected_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE r public.festival_runtime_sessions%ROWTYPE; req public.festival_crowd_recalculation_requests%ROWTYPE; onsite integer; total_weight numeric; remaining integer; allocated integer; row_count integer; c record; old_count integer; target integer; result jsonb; input_digest text; output_digest text; sample_at timestamptz:=clock_timestamp();
BEGIN
 SELECT * INTO r FROM public.festival_runtime_sessions WHERE id=p_runtime_session_id FOR UPDATE;
 IF r.id IS NULL THEN RAISE EXCEPTION 'festival_runtime_chain_session'; END IF;
 PERFORM public._festival_assert_runtime_chain(r.id,p_runtime_day_id,NULL,NULL);
 IF NOT public._festival_runtime_owner(r.id,public._festival_runtime_actor()) THEN RAISE EXCEPTION 'festival_runtime_forbidden'; END IF;
 IF r.version<>p_expected_version THEN RAISE EXCEPTION 'festival_runtime_stale'; END IF;
 IF r.status IN('runtime_complete','cancelled','failed') OR r.completed_at IS NOT NULL THEN RAISE EXCEPTION 'festival_crowd_runtime_finalised'; END IF;
 SELECT a.onsite_count INTO onsite FROM public.festival_runtime_attendance a WHERE a.runtime_session_id=r.id AND a.runtime_day_id=p_runtime_day_id FOR UPDATE;
 IF onsite IS NULL OR onsite<0 THEN RAISE EXCEPTION 'festival_crowd_attendance_invalid'; END IF;
 input_digest:=encode(digest(jsonb_build_object('session',r.id,'day',p_runtime_day_id,'runtimeVersion',r.version,'onsite',onsite,'stages',(SELECT jsonb_agg(jsonb_build_array(s.id,s.status,s.capacity,p.id,p.status,p.delay_minutes) ORDER BY s.id) FROM public.festival_runtime_stages s LEFT JOIN public.festival_runtime_performances p ON p.runtime_stage_id=s.id AND p.runtime_day_id=p_runtime_day_id AND p.status IN('live','starting','ready','delayed') WHERE s.runtime_session_id=r.id),'weather',(SELECT jsonb_agg(to_jsonb(w) ORDER BY w.id) FROM public.festival_runtime_weather w WHERE w.runtime_session_id=r.id AND w.runtime_day_id=p_runtime_day_id))::text,'sha256'),'hex');
 INSERT INTO public.festival_crowd_recalculation_requests(runtime_session_id,runtime_day_id,idempotency_key,input_digest,sample_time) VALUES(r.id,p_runtime_day_id,p_idempotency_key,input_digest,sample_at) ON CONFLICT DO NOTHING;
 SELECT * INTO req FROM public.festival_crowd_recalculation_requests WHERE runtime_session_id=r.id AND runtime_day_id=p_runtime_day_id AND idempotency_key=p_idempotency_key FOR UPDATE;
 IF req.input_digest<>input_digest THEN RAISE EXCEPTION 'festival_crowd_idempotency_conflict'; END IF;
 IF req.status='completed' THEN RETURN req.result||jsonb_build_object('idempotent',true); END IF;
 CREATE TEMP TABLE _festival_alloc(stage_id uuid PRIMARY KEY,performance_id uuid,capacity integer,weight numeric,exact_share numeric,floor_share integer,remainder numeric) ON COMMIT DROP;
 INSERT INTO _festival_alloc(stage_id,performance_id,capacity,weight,exact_share,floor_share,remainder)
 SELECT s.id,p.id,s.capacity,CASE WHEN s.status IN('closed','failed') OR p.id IS NULL OR p.status='cancelled' THEN 0 ELSE greatest(1,50+(get_byte(decode(substr(md5(s.stage_seed||p.id::text),1,2),'hex'),0)%51)+CASE WHEN p.status='live' THEN 35 ELSE 0 END-least(p.delay_minutes,30)) END,0,0,0
 FROM public.festival_runtime_stages s LEFT JOIN LATERAL(SELECT x.* FROM public.festival_runtime_performances x WHERE x.runtime_session_id=r.id AND x.runtime_day_id=p_runtime_day_id AND x.runtime_stage_id=s.id AND x.status IN('live','starting','ready','delayed') ORDER BY x.scheduled_start,x.id LIMIT 1)p ON true WHERE s.runtime_session_id=r.id;
 SELECT coalesce(sum(weight),0) INTO total_weight FROM _festival_alloc;
 UPDATE _festival_alloc SET exact_share=CASE WHEN total_weight=0 THEN 0 ELSE onsite*weight/total_weight END;
 UPDATE _festival_alloc SET floor_share=least(capacity,floor(exact_share)::integer),remainder=exact_share-floor(exact_share);
 SELECT onsite-coalesce(sum(floor_share),0) INTO remaining FROM _festival_alloc;
 WHILE remaining>0 LOOP
  UPDATE _festival_alloc SET floor_share=floor_share+1,remainder=remainder-1 WHERE stage_id=(SELECT stage_id FROM _festival_alloc WHERE weight>0 AND floor_share<capacity ORDER BY remainder DESC,stage_id LIMIT 1);
  GET DIAGNOSTICS row_count=ROW_COUNT; IF row_count=0 THEN EXIT; END IF; remaining:=remaining-1;
 END LOOP;
 allocated:=onsite-remaining;
 FOR c IN SELECT * FROM _festival_alloc ORDER BY stage_id LOOP
  SELECT current_crowd INTO old_count FROM public.festival_runtime_stage_crowds WHERE runtime_day_id=p_runtime_day_id AND runtime_stage_id=c.stage_id; old_count:=coalesce(old_count,0); target:=c.floor_share;
  INSERT INTO public.festival_runtime_stage_crowds(runtime_session_id,runtime_day_id,runtime_stage_id,runtime_performance_id,current_crowd,stage_capacity,crowd_share,arrivals,departures,queue_size,safety_pressure,peak_audience,audience_total,sample_count,seed,formula_version,last_calculated_at)
  VALUES(r.id,p_runtime_day_id,c.stage_id,c.performance_id,target,c.capacity,CASE WHEN onsite=0 THEN 0 ELSE target::numeric/onsite END,greatest(target-old_count,0),greatest(old_count-target,0),0,CASE WHEN c.capacity=0 THEN 0 ELSE least(100,round(target::numeric/c.capacity*100)) END,target,target,1,encode(digest(r.runtime_seed||':crowd:'||p_runtime_day_id||':'||c.stage_id,'sha256'),'hex'),'festival-crowd-largest-remainder-v2',sample_at)
  ON CONFLICT(runtime_day_id,runtime_stage_id) DO UPDATE SET runtime_performance_id=excluded.runtime_performance_id,current_crowd=excluded.current_crowd,crowd_share=excluded.crowd_share,arrivals=excluded.arrivals,departures=excluded.departures,safety_pressure=excluded.safety_pressure,peak_audience=greatest(public.festival_runtime_stage_crowds.peak_audience,excluded.current_crowd),audience_total=public.festival_runtime_stage_crowds.audience_total+excluded.current_crowd,sample_count=public.festival_runtime_stage_crowds.sample_count+1,formula_version=excluded.formula_version,last_calculated_at=excluded.last_calculated_at,version=public.festival_runtime_stage_crowds.version+1;
  INSERT INTO public.festival_runtime_crowd_movements(runtime_session_id,runtime_day_id,to_stage_id,arrivals,departures,reason,calculation_key) VALUES(r.id,p_runtime_day_id,c.stage_id,greatest(target-old_count,0),greatest(old_count-target,0),'largest_remainder',req.id||':'||c.stage_id) ON CONFLICT DO NOTHING;
 END LOOP;
 INSERT INTO public.festival_runtime_crowds(runtime_session_id,runtime_day_id,admitted_count,allocated_count,unallocated_count,seed,formula_version,last_calculated_at) VALUES(r.id,p_runtime_day_id,onsite,allocated,remaining,encode(digest(r.runtime_seed||':crowd:'||p_runtime_day_id,'sha256'),'hex'),'festival-crowd-largest-remainder-v2',sample_at) ON CONFLICT(runtime_day_id) DO UPDATE SET admitted_count=excluded.admitted_count,allocated_count=excluded.allocated_count,unallocated_count=excluded.unallocated_count,formula_version=excluded.formula_version,last_calculated_at=excluded.last_calculated_at,version=public.festival_runtime_crowds.version+1;
 result:=jsonb_build_object('runtimeSessionId',r.id,'runtimeDayId',p_runtime_day_id,'allocated',allocated,'unallocated',remaining,'onsite',onsite,'sampleTime',sample_at,'formulaVersion','festival-crowd-largest-remainder-v2','idempotencyKey',p_idempotency_key,'idempotent',false);
 output_digest:=encode(digest(result::text,'sha256'),'hex'); UPDATE public.festival_crowd_recalculation_requests SET status='completed',result=result,output_digest=output_digest,completed_at=now() WHERE id=req.id;
 RETURN result;
END$$;

CREATE OR REPLACE FUNCTION public.finalise_festival_runtime_outcomes(p_runtime_session_id uuid,p_expected_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE r public.festival_runtime_sessions%ROWTYPE; snapshot jsonb; content_digest text; existing public.festival_runtime_outcome_snapshots%ROWTYPE;
BEGIN
 SELECT * INTO r FROM public.festival_runtime_sessions WHERE id=p_runtime_session_id FOR UPDATE;
 IF r.id IS NULL THEN RAISE EXCEPTION 'festival_runtime_chain_session'; END IF; PERFORM public._festival_assert_runtime_chain(r.id,NULL,NULL,NULL);
 IF NOT public._festival_runtime_owner(r.id,public._festival_runtime_actor()) THEN RAISE EXCEPTION 'festival_runtime_forbidden'; END IF;
 SELECT * INTO existing FROM public.festival_runtime_outcome_snapshots WHERE runtime_session_id=r.id; IF existing.id IS NOT NULL THEN RETURN jsonb_build_object('readyForSettlement',true,'outcomeDigest',existing.content_digest,'idempotent',true); END IF;
 IF r.version<>p_expected_version THEN RAISE EXCEPTION 'festival_runtime_stale'; END IF;
 IF r.status NOT IN('public_closed','site_clearance') OR r.gates_open OR EXISTS(SELECT 1 FROM public.festival_performance_simulation_jobs WHERE runtime_session_id=r.id AND status<>'completed') OR EXISTS(SELECT 1 FROM public.festival_runtime_performances p WHERE p.runtime_session_id=r.id AND p.status NOT IN('completed','cancelled','abandoned','failed')) OR EXISTS(SELECT 1 FROM public.festival_runtime_incidents WHERE runtime_session_id=r.id AND severity IN('major','critical') AND status NOT IN('resolved','handed_over')) OR EXISTS(SELECT 1 FROM public.festival_runtime_vendor_sales WHERE runtime_session_id=r.id AND status='open') OR EXISTS(SELECT 1 FROM public.festival_runtime_sponsor_activations WHERE runtime_session_id=r.id AND status IN('planned','ready','active')) OR EXISTS(SELECT 1 FROM public.festival_runtime_attendance a LEFT JOIN public.festival_runtime_crowds c ON c.runtime_day_id=a.runtime_day_id WHERE a.runtime_session_id=r.id AND coalesce(c.allocated_count,0)+coalesce(c.unallocated_count,0)<>a.onsite_count) THEN RAISE EXCEPTION 'festival_runtime_outcomes_blocked'; END IF;
 snapshot:=jsonb_build_object('performances',(SELECT jsonb_agg(to_jsonb(x) ORDER BY x.runtime_performance_id) FROM public.festival_performance_simulation_results x JOIN public.festival_runtime_performances p ON p.id=x.runtime_performance_id WHERE p.runtime_session_id=r.id),'crowds',(SELECT jsonb_agg(to_jsonb(x) ORDER BY x.runtime_day_id,x.runtime_stage_id) FROM public.festival_runtime_stage_crowds x WHERE x.runtime_session_id=r.id),'attendance',(SELECT jsonb_agg(to_jsonb(x) ORDER BY x.runtime_day_id) FROM public.festival_runtime_attendance x WHERE x.runtime_session_id=r.id),'sourceDigests',jsonb_build_object('performanceInputs',(SELECT jsonb_agg(input_digest ORDER BY runtime_performance_id) FROM public.festival_performance_simulation_jobs WHERE runtime_session_id=r.id),'crowdInputs',(SELECT jsonb_agg(input_digest ORDER BY runtime_day_id,created_at) FROM public.festival_crowd_recalculation_requests WHERE runtime_session_id=r.id AND status='completed')));
 content_digest:=encode(digest(snapshot::text,'sha256'),'hex'); INSERT INTO public.festival_runtime_outcome_snapshots(runtime_session_id,snapshot,engine_version,formula_versions,content_digest) VALUES(r.id,snapshot,r.engine_version,jsonb_build_object('runtime',r.formula_version,'crowd','festival-crowd-largest-remainder-v2'),content_digest);
 UPDATE public.festival_runtime_sessions SET status='runtime_complete',ready_for_settlement=true,completed_at=now(),gates_open=false,version=version+1,updated_at=now() WHERE id=r.id;
 RETURN jsonb_build_object('readyForSettlement',true,'outcomeDigest',content_digest,'idempotencyKey',p_idempotency_key,'idempotent',false);
END$$;

GRANT EXECUTE ON FUNCTION public._festival_assert_runtime_chain(uuid,uuid,uuid,uuid),public.get_festival_performance_simulation_jobs(uuid),public.recalculate_festival_crowds(uuid,uuid,integer,uuid),public.resolve_festival_performance(uuid,integer,uuid),public.finalise_festival_runtime_outcomes(uuid,integer,uuid) TO authenticated;
